import importlib.util, csv, sys, time, numpy as np, pymc as pm
def load(p,n):
    s=importlib.util.spec_from_file_location(n,p); m=importlib.util.module_from_spec(s); s.loader.exec_module(m); return m
rows=list(csv.DictReader(open('responses.csv')))
new=load('iter_2/candidate_2/candidate.py','new'); old=load('models/anchored_neighbourhood_side_channel.py','old')
pt_={'lambda_0':0.4,'beta':0.8,'eps':0.2,'gamma':0.5,'sigma':15.,'kappa':1.0,'alpha':0.2,'rho':1.0,'omega':0.3}
out=[]
for m,z in ((old,None),(new,0.0)):
    with m.model: pm.set_data(m.prepare_observed(rows))
    ip=m.model.initial_point(); vals={}
    for v in m.model.free_RVs:
        val=pt_.get(v.name, z)
        vals[m.model.rvs_to_values[v].name]=m.model.rvs_to_transforms[v].forward(val).eval() if m.model.rvs_to_transforms[v] is not None else val
    f=m.model.compile_fn(m.model['p_yes'],inputs=m.model.value_vars,on_unused_input='ignore')
    out.append(f(vals))
    if m is new:
        g=m.model.compile_dlogp(); ip.update(vals); g(ip); t=time.time()
        for _ in range(20): g(ip)
        print('grad ms',(time.time()-t)/20*1000)
print('max abs diff',np.abs(out[0]-out[1]).max())
EOF
